package com.jonathancruzate.metamusewidget;

import android.content.Context;
import android.content.SharedPreferences;

/**
 * Muse Launcher Pack preferences (Pack v5.0.0). A NEW preference
 * file beside the frozen WidgetPrefs: the search bar's store is
 * byte-stable by rule, so every pack setting (tile kinds, the
 * Device Assistance pairing token, context snapshots, theme mode)
 * lives here instead. The pairing token exists only on this phone:
 * it is generated by Device Assistance at pairing time, stored
 * here and there, never compiled, never backed up (the app sets
 * allowBackup=false), never logged.
 */
final class PackPrefs {

    private static final String FILE = "muse_pack";

    private PackPrefs() {}

    private static SharedPreferences prefs(Context ctx) {
        return ctx.getSharedPreferences(FILE, Context.MODE_PRIVATE);
    }

    // ---- Tile kinds (per widget instance) ----

    static String kindFor(Context ctx, int widgetId, String def) {
        return prefs(ctx).getString("kind_" + widgetId, def);
    }

    static void setKind(Context ctx, int widgetId, String kind) {
        prefs(ctx).edit().putString("kind_" + widgetId, kind).apply();
    }

    static void clearKind(Context ctx, int widgetId) {
        prefs(ctx).edit().remove("kind_" + widgetId).apply();
    }

    // ---- Device Assistance pairing ----

    static String daToken(Context ctx) {
        return prefs(ctx).getString("da_token", "");
    }

    static boolean daPaired(Context ctx) {
        return prefs(ctx).getBoolean("da_paired", false)
                && !daToken(ctx).isEmpty();
    }

    static void setDaToken(Context ctx, String token) {
        prefs(ctx).edit()
                .putString("da_token", token == null ? "" : token)
                .putBoolean("da_paired", token != null && !token.isEmpty())
                .apply();
    }

    static void clearDaToken(Context ctx) {
        prefs(ctx).edit().remove("da_token")
                .putBoolean("da_paired", false).apply();
    }

    // ---- Context snapshots (written by ContextReceiver) ----

    static void putContextHouseMode(Context ctx, String mode) {
        prefs(ctx).edit().putString("ctx_house_mode", mode)
                .putLong("ctx_house_mode_at", System.currentTimeMillis())
                .apply();
    }

    static String contextHouseMode(Context ctx) {
        return prefs(ctx).getString("ctx_house_mode", "");
    }

    static void putContextMedia(Context ctx, String text) {
        prefs(ctx).edit().putString("ctx_media_text", text)
                .putLong("ctx_media_at", System.currentTimeMillis())
                .apply();
    }

    /** Media snapshot text when fresher than 30 minutes, else null. */
    static String contextMedia(Context ctx) {
        long at = prefs(ctx).getLong("ctx_media_at", 0);
        if (at == 0
                || System.currentTimeMillis() - at > 30L * 60L * 1000L) {
            return null;
        }
        String t = prefs(ctx).getString("ctx_media_text", "");
        return t.isEmpty() ? null : t;
    }

    // ---- Last known DND state (House Control toggle memory) ----

    static boolean contextDndOn(Context ctx) {
        return prefs(ctx).getBoolean("ctx_dnd_on", false);
    }

    static void putContextDndOn(Context ctx, boolean on) {
        prefs(ctx).edit().putBoolean("ctx_dnd_on", on).apply();
    }

    // ---- Theme mode (Pack v5.2.0 per-mode theming) ----

    /** auto | day | night | work. Auto follows the house mode. */
    static String themeMode(Context ctx) {
        return prefs(ctx).getString("theme_mode", "auto");
    }

    static void setThemeMode(Context ctx, String mode) {
        prefs(ctx).edit().putString("theme_mode", mode).apply();
    }

    // ---- Sleep tile cache (Pack v5.2.0) ----

    static void putSleepSummary(Context ctx, String text) {
        prefs(ctx).edit().putString("sleep_summary", text)
                .putLong("sleep_at", System.currentTimeMillis()).apply();
    }

    static long sleepSummaryAt(Context ctx) {
        return prefs(ctx).getLong("sleep_at", 0L);
    }

    static String sleepSummary(Context ctx) {
        String t = prefs(ctx).getString("sleep_summary", "");
        return t.isEmpty() ? null : t;
    }

    // ---- Grid widget favorites ----

    static final String[] DEFAULT_GRID_PACKAGES = {
            "com.facebook.aura",
            "com.google.android.apps.messaging",
            "com.samsung.android.dialer",
            "com.sec.android.app.camera",
            "com.samsung.android.app.smartthings",
            "com.google.android.apps.maps",
            "com.spotify.music",
            "com.android.settings",
    };

    static String[] gridPackages(Context ctx) {
        String saved = prefs(ctx).getString("grid_packages", "");
        if (saved == null || saved.isEmpty()) return DEFAULT_GRID_PACKAGES;
        return saved.split(",");
    }
}
